  assert.equal(median_doc([25, 25, 4, 4]), 14.5);
});

// config-parser | parse-and-validate / split-scan | duplicates / p4

function parseConfig(input: string): Record<string, string> {
  const result: Record<string, string> = {};
  for (const rawLine of input.split("\n")) {
    const line = rawLine.trim();
    if (line.length === 0 || line.startsWith("#")) continue;
    const separator = line.indexOf("=");
    if (separator <= 0) throw new Error(`invalid line: ${line}`);
    const key = line.slice(0, separator).trim();
    const value = line.slice(separator + 1).trim();
    if (key in result) throw new Error(`duplicate key: ${key}`);
    result[key] = value;
  }
  return result;
}

